","quality_summary.py":"from google.cloud import language_v1


def quality_summary(text, locale='en'):
    client = language_v1.LanguageServiceClient()
    document = language_v1.Document(content=text, type_=language_v1.Document.Type.PLAIN_TEXT, language=locale)
    sentiment = client.analyze_sentiment(request={'document': document}).document_sentiment
    issues = []
    if sentiment.score < -0.25:
        issues.append('negative_tone')
    if len(text.strip()) == 0:
        issues.append('empty_output')
    if any(token in text.lower() for token in ['??', '!!!', 'TODO']):
        issues.append('formatting_or_placeholder_issue')
    return {'score': float(getattr(sentiment, 'score', 0.0)), 'magnitude': float(getattr(sentiment, 'magnitude', 0.0)), 'issues': issues}
","unsafe_copy_check.py":"import re
from google.cloud import dlp_v2


_UNSAFE_PATTERNS = [re.compile(p, re.I) for p in [r'\bpassword\b', r'\bssn\b', r'credit card', r'\bapi[_ -]?key\b']]


def unsafe_copy_check(text, project_id=None):
    findings = []
    for pattern in _UNSAFE_PATTERNS:
        if pattern.search(text):
            findings.append(pattern.pattern)
    client = dlp_v2.DlpServiceClient()
    if project_id:
        parent = f'projects/{project_id}'
        content_item = {'value': text}
        _ = client.inspect_content(request={'parent': parent, 'item': content_item})
    return {'unsafe': bool(findings), 'findings': findings}
